query:
SELECT category, COUNT(*) as total, SUM(CASE WHEN isActive = 1 THEN 1 ELSE 0 END) as active_count
FROM quickfire_questions
GROUP BY category
ORDER BY category;

SELECT id, title, category, status, publishDate, publishedAt, archivedAt
FROM quickfire_challenges
WHERE status = 'live'
ORDER BY category
LIMIT 20;

SELECT setDate, questionIds FROM quickfire_daily_sets ORDER BY setDate DESC LIMIT 3;
